"""Hardware-free test world. No goal is ever generated by this module."""
import asyncio
import math
import time
import numpy as np
from pi_car.common.grid import GridMetadata, OccupancyGrid
from pi_car.common.messages import Pose
from pi_car.pc.fleet import FleetController
from pi_car.pc.server import FleetTCPServer
from pi_car.vehicle.agent import RobotAgent
from pi_car.vehicle.client import RobotClient
from pi_car.vehicle.hardware import DisabledMotor
from pi_car.vehicle.perception import RangeReading


def mock_grid():
    cells = np.zeros((30, 40), dtype=np.int8)
    cells[[0,-1],:] = 1
    cells[:,[0,-1]] = 1
    return OccupancyGrid(cells, GridMetadata(40,30,.1,(0.,0.),"mock-floor","mock-v1","mock"))


class MockFleet:
    """Mock localization integrates dry motor outputs, then sends poses through TCP.

    This supplies simulated external observations; Pi clients still receive POSE,
    plan locally and execute the production runtime. It is not a hardware model.
    """
    def __init__(self, *, host="127.0.0.1", port=0):
        self.grid = mock_grid()
        self.fleet = FleetController(self.grid, ["A","B"], clearance_m=.2)
        self.server = FleetTCPServer(self.fleet, host, port, timeout_s=.6, heartbeat_s=.1)
        self.motors = {r: DisabledMotor() for r in self.fleet.robots}
        self.agents = {r: RobotAgent(r,self.grid,motor=m,clearance_m=.2,watchdog_s=.3)
                       for r,m in self.motors.items()}
        self.positions = {"A":[1.,1.,0.], "B":[1.,2.,0.]}
        self.range_m = {"A":1.,"B":1.}
        self.visible = {"A":True,"B":True}
        self.clients = {}
        self.tasks = []

    async def start(self):
        await self.server.start()
        for r,agent in self.agents.items():
            client = RobotClient(agent,self.server.host,self.server.port,timeout_s=.6,
                                 heartbeat_s=.1,reconnect_s=.05,
                                 range_provider=lambda r=r: RangeReading(self.range_m[r],0.,time.monotonic()))
            self.clients[r] = client
            self.tasks.append(asyncio.create_task(client.run()))
        self.tasks.append(asyncio.create_task(self._world()))
        return self

    async def _world(self):
        previous = time.monotonic()
        while True:
            now = time.monotonic()
            dt, previous = min(now-previous,.05), now
            for r, motor in self.motors.items():
                left,right = motor.last_command.left,motor.last_command.right
                x,y,theta = self.positions[r]
                # Mock normalization only: this is not an Adeept speed calibration.
                velocity = (left+right)/2*3.
                angular = (right-left)/.25*3.
                theta += angular*dt
                x += velocity*math.cos(theta)*dt
                y += velocity*math.sin(theta)*dt
                self.positions[r] = [x,y,theta]
            await asyncio.gather(*(self.fleet.publish_pose(
                r, Pose(r,*self.positions[r],time.time(),self.grid.metadata.frame_id)
                if self.visible[r] else None) for r in self.positions))
            await asyncio.sleep(.015)

    async def close(self):
        for client in self.clients.values():
            await client.close()
        for task in self.tasks:
            task.cancel()
        await asyncio.gather(*self.tasks, return_exceptions=True)
        await self.server.close()
        for agent in self.agents.values():
            await agent.close()
        self.fleet.close()
